// Package sessionjsonl provides shared low-level reads for append-only agent
// session files.
package sessionjsonl

import (
	"bufio"
	"bytes"
	"errors"
	"io"
	"os"
)

const reverseBlockSize = 64 * 1024

// CompleteEnd returns the byte immediately after the last newline-terminated
// record. A trailing partial record is excluded without classifying the file.
func CompleteEnd(path string) (int64, error) {
	file, err := os.Open(path)
	if err != nil {
		return 0, err
	}
	defer file.Close()
	stat, err := file.Stat()
	if err != nil {
		return 0, err
	}
	return completeEnd(file, stat.Size(), make([]byte, reverseBlockSize))
}

// ScanCompleteTail snapshots the current complete-input end, inspects complete
// records oldest-first when inspect is non-nil, then visits them newest-first
// with stable zero-based line numbers and byte offsets. The reverse scan stops
// when visit returns false. Appends after the snapshot are left for the next
// read; truncation during the scan returns an error.
func ScanCompleteTail(path string, inspect func([]byte), visit func(raw []byte, line, offset int64) bool) (int64, error) {
	file, err := os.Open(path)
	if err != nil {
		return 0, err
	}
	defer file.Close()
	stat, err := file.Stat()
	if err != nil {
		return 0, err
	}
	buffer := make([]byte, reverseBlockSize)
	end, err := completeEnd(file, stat.Size(), buffer)
	if err != nil || end == 0 {
		return end, err
	}
	lines, err := inspectComplete(file, end, buffer, inspect)
	if err != nil {
		return 0, err
	}
	currentEnd := end
	line := lines - 1
	for currentEnd > 0 {
		lineEnd := currentEnd - 1
		newline, err := previousNewline(file, lineEnd, buffer)
		if err != nil {
			return 0, err
		}
		lineStart := newline + 1
		raw := make([]byte, lineEnd-lineStart)
		if len(raw) > 0 {
			if _, err := file.ReadAt(raw, lineStart); err != nil {
				if errors.Is(err, io.EOF) {
					return 0, io.ErrUnexpectedEOF
				}
				return 0, err
			}
		}
		raw = bytes.TrimSuffix(raw, []byte{'\r'})
		if !visit(raw, line, lineStart) {
			break
		}
		line--
		currentEnd = lineStart
	}
	return end, nil
}

func inspectComplete(file *os.File, end int64, buffer []byte, inspect func([]byte)) (int64, error) {
	if inspect == nil {
		var lines, offset int64
		for offset < end {
			count := int(min(int64(len(buffer)), end-offset))
			n, err := file.ReadAt(buffer[:count], offset)
			lines += int64(bytes.Count(buffer[:n], []byte{'\n'}))
			offset += int64(n)
			if errors.Is(err, io.EOF) {
				return 0, io.ErrUnexpectedEOF
			}
			if err != nil {
				return 0, err
			}
		}
		return lines, nil
	}
	reader := bufio.NewReader(io.NewSectionReader(file, 0, end))
	var lines int64
	for {
		raw, err := reader.ReadBytes('\n')
		if errors.Is(err, io.EOF) && len(raw) == 0 {
			return lines, nil
		}
		if err != nil {
			return 0, err
		}
		body := bytes.TrimSuffix(raw[:len(raw)-1], []byte{'\r'})
		inspect(body)
		lines++
	}
}

// ScanCompleteReverse visits complete JSONL records newest-first and returns
// the complete-record end it scanned from, captured once before the first
// visit. A trailing partial record is ignored, matching the transcript
// readers' append contract. Scanning stops when visit returns false. Callers
// that seed an incremental tail continue from the returned end so bytes
// appended during the scan are never inside the offset unfolded.
func ScanCompleteReverse(path string, visit func([]byte) bool) (int64, error) {
	file, err := os.Open(path)
	if err != nil {
		return 0, err
	}
	defer file.Close()
	stat, err := file.Stat()
	if err != nil {
		return 0, err
	}
	buffer := make([]byte, reverseBlockSize)
	completeEnd, err := completeEnd(file, stat.Size(), buffer)
	if err != nil || completeEnd == 0 {
		return 0, err
	}
	scannedEnd := completeEnd
	for completeEnd > 0 {
		lineEnd := completeEnd - 1
		newline, err := previousNewline(file, lineEnd, buffer)
		if err != nil {
			return scannedEnd, err
		}
		lineStart := newline + 1
		line := make([]byte, lineEnd-lineStart)
		if len(line) > 0 {
			if _, err := file.ReadAt(line, lineStart); err != nil && err != io.EOF {
				return scannedEnd, err
			}
		}
		line = bytes.TrimSuffix(line, []byte{'\r'})
		if !visit(line) {
			return scannedEnd, nil
		}
		completeEnd = lineStart
	}
	return scannedEnd, nil
}

func completeEnd(file *os.File, size int64, buffer []byte) (int64, error) {
	if size == 0 {
		return 0, nil
	}
	last := []byte{0}
	if _, err := file.ReadAt(last, size-1); err != nil {
		return 0, err
	}
	if last[0] == '\n' {
		return size, nil
	}
	newline, err := previousNewline(file, size, buffer)
	if err != nil {
		return 0, err
	}
	return newline + 1, nil
}

func previousNewline(file *os.File, before int64, buffer []byte) (int64, error) {
	for before > 0 {
		start := max(int64(0), before-int64(len(buffer)))
		count := int(before - start)
		if _, err := file.ReadAt(buffer[:count], start); err != nil && err != io.EOF {
			return -1, err
		}
		if index := bytes.LastIndexByte(buffer[:count], '\n'); index >= 0 {
			return start + int64(index), nil
		}
		before = start
	}
	return -1, nil
}

package servecmd

import (
	"encoding/json"
	"errors"
	"fmt"
	"net/http"
	"os"
	"strconv"

	"ai-config/tools/herder/internal/claudesession"
	"ai-config/tools/herder/internal/codexsession"
	"ai-config/tools/herder/internal/hcomidentity"
	"ai-config/tools/herder/internal/sessionjsonl"
	"ai-config/tools/herder/internal/sessionvitals"
)

const maxEntryWindow = 500

type entriesWindow struct {
	Mode  string `json:"mode"`
	From  int64  `json:"from"`
	Limit int    `json:"limit"`
}

type entriesStats struct {
	SidechainSkipped int `json:"sidechainSkipped"`
}

type entryResponse struct {
	UUID       string                    `json:"uuid,omitempty"`
	Line       int64                     `json:"line"`
	ByteOffset int64                     `json:"byteOffset"`
	Timestamp  string                    `json:"timestamp,omitempty"`
	Kind       claudesession.Kind        `json:"kind"`
	Payload    json.RawMessage           `json:"payload"`
	Quarantine *claudesession.Quarantine `json:"quarantine,omitempty"`
}

type entriesResponse struct {
	SessionID  string               `json:"sessionId"`
	Window     entriesWindow        `json:"window"`
	Entries    *[]entryResponse     `json:"entries,omitempty"`
	NextOffset *int64               `json:"nextOffset,omitempty"`
	Reset      *claudesession.Reset `json:"reset,omitempty"`
	Stats      *entriesStats        `json:"stats,omitempty"`
}

func serveEntries(w http.ResponseWriter, r *http.Request, deps dependencies, name string) {
	limit, err := entryLimit(r)
	if err != nil {
		refuse(w, http.StatusBadRequest, "bad request", err.Error())
		return
	}
	from, hasFrom, err := entryOffset(r)
	if err != nil {
		refuse(w, http.StatusBadRequest, "bad request", err.Error())
		return
	}
	previousSessionID := r.URL.Query().Get("sessionId")
	if !hasFrom && previousSessionID != "" {
		refuse(w, http.StatusBadRequest, "bad request", "sessionId requires from")
		return
	}

	row, err := entryAgent(deps, name)
	if err != nil {
		serveAgentReadError(w, err)
		return
	}
	home, err := os.UserHomeDir()
	if err != nil {
		refuse(w, http.StatusBadGateway, "substrate unreachable", err.Error())
		return
	}
	path, err := sessionvitals.ResolvePath(home, row)
	if err != nil {
		var resolveErr *claudesession.ResolveError
		var codexResolveErr *codexsession.ResolveError
		if errors.As(err, &resolveErr) && unavailableSubagentTranscript(row, resolveErr) {
			refuse(w, http.StatusConflict, "no independent transcript", err.Error())
			return
		}
		if resolveErr != nil || errors.As(err, &codexResolveErr) {
			refuse(w, http.StatusConflict, "no session", err.Error())
			return
		}
		refuse(w, http.StatusBadGateway, "substrate unreachable", err.Error())
		return
	}

	window := entriesWindow{Mode: "from", From: from, Limit: limit}
	currentTranscriptID := entryTranscriptID(row)
	var read claudesession.ReadResult
	if hasFrom {
		tail, tailErr := readEntryWindow(path, row, claudesession.Cursor{SessionID: previousSessionID, Offset: from}, limit)
		if tailErr != nil {
			refuse(w, http.StatusBadGateway, "substrate unreachable", tailErr.Error())
			return
		}
		if tail.Reset != nil {
			writeJSON(w, http.StatusOK, entriesResponse{SessionID: currentTranscriptID, Window: window, Reset: tail.Reset})
			return
		}
		read = tail.Read
	} else {
		window.Mode = "tail"
		read, window.From, err = readEntryTail(path, row, limit)
		if err != nil {
			refuse(w, http.StatusBadGateway, "substrate unreachable", err.Error())
			return
		}
	}

	entries := serializeEntries(read.Entries)
	next := read.NextOffset
	stats := entriesStats{SidechainSkipped: read.Stats.SidechainSkipped}
	writeJSON(w, http.StatusOK, entriesResponse{
		SessionID: currentTranscriptID, Window: window, Entries: &entries,
		NextOffset: &next, Stats: &stats,
	})
}

func unavailableSubagentTranscript(row hcomidentity.Row, resolveErr *claudesession.ResolveError) bool {
	if !isSubagent(row) {
		return false
	}
	switch resolveErr.Reason {
	case claudesession.ResolveMissingParent, claudesession.ResolveFileAbsent, claudesession.ResolveAmbiguousFile:
		return true
	default:
		return false
	}
}

// serializeEntries is the single wire projection shared by entry windows and
// multiplexed entry frames. Those two surfaces must never drift in shape.
func serializeEntries(entries []claudesession.Entry) []entryResponse {
	serialized := make([]entryResponse, len(entries))
	for i, entry := range entries {
		serialized[i] = entryResponse{
			UUID: entry.UUID, Line: entry.Line, ByteOffset: entry.ByteOffset,
			Timestamp: entry.Timestamp, Kind: entry.Kind, Payload: entry.Payload,
			Quarantine: entry.Quarantine,
		}
	}
	return serialized
}

func entryLimit(r *http.Request) (int, error) {
	limit := maxEntryWindow
	if raw := r.URL.Query().Get("limit"); raw != "" {
		parsed, err := strconv.Atoi(raw)
		if err != nil || parsed < 1 || parsed > maxEntryWindow {
			return 0, fmt.Errorf("limit must be an integer from 1 through %d", maxEntryWindow)
		}
		limit = parsed
	}
	return limit, nil
}

func entryOffset(r *http.Request) (int64, bool, error) {
	raw, present := r.URL.Query()["from"]
	if !present {
		return 0, false, nil
	}
	if len(raw) != 1 {
		return 0, false, errors.New("from must be one non-negative byte offset")
	}
	offset, err := strconv.ParseInt(raw[0], 10, 64)
	if err != nil || offset < 0 {
		return 0, false, errors.New("from must be one non-negative byte offset")
	}
	return offset, true, nil
}

func entryAgent(deps dependencies, name string) (hcomidentity.Row, error) {
	row, _, _, err := resolveAgentEvidence(deps, name)
	return row, err
}

func entryTailEnd(row hcomidentity.Row) (int64, error) {
	home, err := os.UserHomeDir()
	if err != nil {
		return 0, err
	}
	path, err := sessionvitals.ResolvePath(home, row)
	if err != nil {
		return 0, err
	}
	return sessionjsonl.CompleteEnd(path)
}

func entryTail(row hcomidentity.Row, cursor claudesession.Cursor, limit int) (claudesession.TailResult, error) {
	home, err := os.UserHomeDir()
	if err != nil {
		return claudesession.TailResult{}, err
	}
	path, err := sessionvitals.ResolvePath(home, row)
	if err != nil {
		return claudesession.TailResult{}, err
	}
	if row.Tool == "codex" {
		return codexsession.TailWindow(path, entryTranscriptID(row), cursor, limit)
	}
	if isSubagent(row) {
		return claudesession.TailSubagentWindow(path, entryTranscriptID(row), cursor, limit)
	}
	return claudesession.TailWindow(path, entryTranscriptID(row), cursor, limit)
}

func entrySessionPath(row hcomidentity.Row) (string, error) {
	home, err := os.UserHomeDir()
	if err != nil {
		return "", err
	}
	return sessionvitals.ResolvePath(home, row)
}

// readQueueExclusions scans normalized session windows without retaining the
// full transcript. Delivered IDs are excluded for every supported tool;
// pre-compaction candidates are also excluded for Claude, whose compaction can
// erase their structural delivery evidence. Codex rollouts remain append-only.
func readQueueExclusions(row hcomidentity.Row, candidates map[string]queueCandidate) (map[string]bool, error) {
	proof := newQueueProof(row.Tool == "claude")
	if len(candidates) == 0 {
		return proof.exclusions(candidates)
	}
	if row.Tool != "claude" && row.Tool != "codex" {
		return nil, fmt.Errorf("unsupported session tool %q", row.Tool)
	}
	home, err := os.UserHomeDir()
	if err != nil {
		return nil, err
	}
	path, err := sessionvitals.ResolvePath(home, row)
	if err != nil {
		return nil, err
	}
	var offset int64
	for {
		var read claudesession.ReadResult
		if row.Tool == "codex" {
			read, err = codexsession.ReadWindow(path, offset, maxEntryWindow)
		} else if isSubagent(row) {
			read, err = claudesession.ReadSubagentWindow(path, offset, maxEntryWindow)
		} else {
			read, err = claudesession.ReadWindow(path, offset, maxEntryWindow)
		}
		if err != nil {
			return nil, err
		}
		if err := proof.observe(read.Entries, candidates); err != nil {
			return nil, err
		}
		if len(proof.excluded) == len(candidates) {
			return proof.exclusions(candidates)
		}
		if read.NextOffset == offset {
			return proof.exclusions(candidates)
		}
		offset = read.NextOffset
	}
}

func readEntryWindow(path string, row hcomidentity.Row, cursor claudesession.Cursor, limit int) (claudesession.TailResult, error) {
	if row.Tool == "codex" {
		return codexsession.TailWindow(path, entryTranscriptID(row), cursor, limit)
	}
	if isSubagent(row) {
		return claudesession.TailSubagentWindow(path, entryTranscriptID(row), cursor, limit)
	}
	return claudesession.TailWindow(path, entryTranscriptID(row), cursor, limit)
}

func readEntryTail(path string, row hcomidentity.Row, limit int) (claudesession.ReadResult, int64, error) {
	if row.Tool == "codex" {
		return codexsession.ReadTail(path, limit)
	}
	if isSubagent(row) {
		return claudesession.ReadSubagentTail(path, limit)
	}
	return claudesession.ReadTail(path, limit)
}

func isSubagent(row hcomidentity.Row) bool {
	return row.Tool == "claude" && row.AgentID != ""
}

func entryTranscriptID(row hcomidentity.Row) string {
	if isSubagent(row) {
		return "subagent:" + row.AgentID
	}
	return row.SessionID
}

